// ---------- helpers
const hexToRgb = (h) => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });
const solid = (h) => [{ type: "SOLID", color: hexToRgb(h) }];

let F = null; // выбранные шрифты
const paint = {}; // имя стиля -> PaintStyle
const typo = {}; // имя стиля -> TextStyle

async function pickFonts() {
  const candidates = [
    { family: "VTB Group UI", book: "Book", medium: "Medium", semi: "Semi Bold" },
    { family: "Inter", book: "Regular", medium: "Medium", semi: "Semi Bold" },
  ];
  for (const c of candidates) {
    try {
      const fonts = { book: { family: c.family, style: c.book }, medium: { family: c.family, style: c.medium }, semi: { family: c.family, style: c.semi } };
      await Promise.all(Object.values(fonts).map((f) => figma.loadFontAsync(f)));
      return { ...fonts, family: c.family };
    } catch (e) { /* пробуем следующий */ }
  }
  throw new Error("Не удалось загрузить ни VTB Group UI, ни Inter");
}

async function ensurePaintStyles() {
  const existing = await figma.getLocalPaintStylesAsync();
  for (const [name, hex] of COLORS) {
    let s = existing.find((x) => x.name === name);
    if (!s) { s = figma.createPaintStyle(); s.name = name; }
    s.paints = solid(hex);
    paint[name] = s;
  }
}

async function ensureTextStyles() {
  const defs = [
    ["Heading/Display", "semi", 56, 64],
    ["Heading/H1", "semi", 32, 40],
    ["Heading/H2", "semi", 24, 32],
    ["Body/L", "book", 18, 26],
    ["Body/M", "book", 16, 24],
    ["Body/M Medium", "medium", 16, 24],
    ["Caption", "book", 14, 20],
    ["Label", "medium", 14, 20],
    ["Tag/Name", "book", 18, 24],
    ["Button/S", "medium", 14, 20],
    ["Button/M", "medium", 16, 24],
    ["Button/L", "medium", 18, 24],
  ];
  const existing = await figma.getLocalTextStylesAsync();
  for (const [name, w, size, lh] of defs) {
    let s = existing.find((x) => x.name === name);
    if (!s) { s = figma.createTextStyle(); s.name = name; }
    s.fontName = F[w];
    s.fontSize = size;
    s.lineHeight = { unit: "PIXELS", value: lh };
    typo[name] = s;
  }
}

async function fillWith(node, styleName) { await node.setFillStyleIdAsync(paint[styleName].id); }
async function strokeWith(node, styleName) { await node.setStrokeStyleIdAsync(paint[styleName].id); }

async function text(chars, styleName, colorStyle = "Neutral/Dark") {
  const t = figma.createText();
  t.fontName = F.book;
  t.characters = chars;
  await t.setTextStyleIdAsync(typo[styleName].id);
  await fillWith(t, colorStyle);
  return t;
}

function autoLayout(dir, props = {}) {
  const f = figma.createFrame();
  f.layoutMode = dir;
  f.primaryAxisSizingMode = "AUTO";
  f.counterAxisSizingMode = "AUTO";
  f.fills = [];
  f.clipsContent = false;
  Object.assign(f, props);
  return f;
}

function gridSet(set, cols, gap = 32, pad = 40) {
  const kids = set.children;
  const cw = Math.max(...kids.map((k) => k.width));
  const rowsH = [];
  kids.forEach((k, i) => { const r = Math.floor(i / cols); rowsH[r] = Math.max(rowsH[r] || 0, k.height); });
  kids.forEach((k, i) => {
    const c = i % cols, r = Math.floor(i / cols);
    k.x = pad + c * (cw + gap);
    k.y = pad + rowsH.slice(0, r).reduce((a, b) => a + b + gap, 0);
  });
  const w = pad * 2 + cols * cw + (cols - 1) * gap;
  const h = pad * 2 + rowsH.reduce((a, b) => a + b, 0) + (rowsH.length - 1) * gap;
  set.resizeWithoutConstraints(w, h);
  set.fills = solid("#FFFFFF");
  set.cornerRadius = 16;
  set.strokes = solid("#DDE3EC");
  set.strokeWeight = 1;
  set.dashPattern = [6, 4];
}

// ---------- components
async function buildCursor() {
  const comps = [];
  for (const [cName, cStyle] of ACCENTS) {
    for (const [fName, fStyle] of CURSOR_FILLS) {
      const comp = figma.createComponent();
      comp.name = `Color=${cName}, Fill=${fName}`;
      comp.resize(55, 65);
      comp.fills = [];
      const svg = figma.createNodeFromSvg(`<svg xmlns="http://www.w3.org/2000/svg" width="55" height="65" viewBox="0 0 55 65" fill="none"><path d="${CURSOR_PATH}" fill="#000000" stroke="#0A76FA" stroke-width="7" stroke-linejoin="round"/></svg>`);
      const vec = svg.children[0];
      comp.appendChild(vec);
      vec.x = 0; vec.y = 0;
      svg.remove();
      vec.name = "arrow";
      await fillWith(vec, fStyle);
      await strokeWith(vec, cStyle);
      comps.push(comp);
    }
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Cursor";
  set.description = "Курсор участника. Color — цвет участника, Fill — заливка внутри.";
  gridSet(set, 3, 32);
  return set;
}

async function buildTag() {
  const comps = [];
  for (const [cName, cStyle, name] of ACCENTS) {
    const comp = figma.createComponent();
    comp.name = `Color=${cName}`;
    comp.layoutMode = "HORIZONTAL";
    comp.primaryAxisSizingMode = "AUTO";
    comp.counterAxisSizingMode = "FIXED";
    comp.resize(100, 36);
    comp.counterAxisAlignItems = "CENTER";
    comp.paddingLeft = comp.paddingRight = 16;
    comp.cornerRadius = 10;
    await fillWith(comp, cStyle);
    const t = await text(name, "Tag/Name", cName === "Yellow" ? "Neutral/Dark" : "Neutral/White");
    t.name = "name";
    comp.appendChild(t);
    comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Tag";
  set.description = "Тег с именем участника. Текст меняется свойством Name.";
  const key = set.addComponentProperty("Name", "TEXT", "Буяков Кирилл");
  for (const c of set.children) {
    const t = c.findOne((n) => n.type === "TEXT");
    t.componentPropertyReferences = { characters: key };
    t.characters = ACCENTS.find((a) => c.name === `Color=${a[0]}`)[2]; // у каждого цвета своё имя
  }
  gridSet(set, 1, 20);
  return set;
}

async function buildCollaborator(cursorSet, tagSet) {
  const comps = [];
  for (const [cName] of ACCENTS) {
    const comp = figma.createComponent();
    comp.name = `Color=${cName}`;
    comp.fills = [];
    comp.clipsContent = false;
    const cur = cursorSet.children.find((c) => c.name === `Color=${cName}, Fill=Dark`).createInstance();
    comp.appendChild(cur);
    cur.rescale(0.5);
    cur.x = 0; cur.y = 0;
    const tag = tagSet.children.find((c) => c.name === `Color=${cName}`).createInstance();
    comp.appendChild(tag);
    tag.x = 12; tag.y = 30;
    comp.resize(12 + tag.width, 30 + tag.height);
    cur.isExposedInstance = true;
    tag.isExposedInstance = true;
    comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Collaborator";
  set.description = "Курсор + тег участника на доске. Вложенные Cursor и Tag открыты для настройки (Fill, Name).";
  gridSet(set, 1, 28);
  return set;
}

const BUTTON_TYPES = {
  Primary: { bg: "Accent/Blue", hover: "UI/Blue Hover", text: "Neutral/White" },
  Secondary: { bg: "UI/Blue Tint", hover: "UI/Blue Tint Hover", text: "Accent/Blue" },
  Outline: { bg: "Neutral/White", hover: "UI/Surface", text: "Neutral/Dark", stroke: "UI/Border" },
  Dark: { bg: "Neutral/Dark", hover: "Neutral/Black", text: "Neutral/White" },
  Ghost: { bg: null, hover: "UI/Surface", text: "Accent/Blue" },
};
const BUTTON_SIZES = { S: { h: 32, pad: 12, r: 8, style: "Button/S" }, M: { h: 36, pad: 16, r: 10, style: "Button/M" }, L: { h: 44, pad: 20, r: 12, style: "Button/L" } };

async function buildButton() {
  const comps = [];
  for (const [type, t] of Object.entries(BUTTON_TYPES)) {
    for (const state of ["Default", "Hover", "Disabled"]) {
      for (const [size, s] of Object.entries(BUTTON_SIZES)) {
        const comp = figma.createComponent();
        comp.name = `Type=${type}, Size=${size}, State=${state}`;
        comp.layoutMode = "HORIZONTAL";
        comp.primaryAxisSizingMode = "AUTO";
        comp.counterAxisSizingMode = "FIXED";
        comp.resize(100, s.h);
        comp.primaryAxisAlignItems = "CENTER";
        comp.counterAxisAlignItems = "CENTER";
        comp.paddingLeft = comp.paddingRight = s.pad;
        comp.cornerRadius = s.r;
        const bg = state === "Hover" ? t.hover : t.bg;
        if (bg) await fillWith(comp, bg); else comp.fills = [];
        if (t.stroke) { await strokeWith(comp, t.stroke); comp.strokeWeight = 1; comp.strokeAlign = "INSIDE"; }
        if (state === "Disabled") comp.opacity = 0.4;
        const label = await text("Открыть доску", s.style, t.text);
        label.name = "label";
        comp.appendChild(label);
        comps.push(comp);
      }
    }
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Button";
  set.description = "Кнопка. Type — вид, Size — S/M/L (32/36/44), State — состояние. Текст — свойство Label.";
  const key = set.addComponentProperty("Label", "TEXT", "Открыть доску");
  for (const c of set.children) c.findOne((n) => n.type === "TEXT").componentPropertyReferences = { characters: key };
  gridSet(set, 9, 16, 24);
  return set;
}

async function buildCanvas() {
  const comps = [];
  for (const [type, tile, base] of [["Miro", TILES.miro, "Canvas/Miro"], ["Holst", TILES.holst, "Canvas/Holst"]]) {
    const comp = figma.createComponent();
    comp.name = `Type=${type}`;
    comp.resize(960, 540);
    const img = figma.createImage(figma.base64Decode(tile));
    const basePaint = paint[base].paints[0];
    comp.fills = [basePaint, { type: "IMAGE", imageHash: img.hash, scaleMode: "TILE", scalingFactor: 0.5 }];
    comp.clipsContent = true;
    comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Canvas";
  set.description = "Фон рабочей области доски. Miro — сетка 24 px с акцентом каждые 96 px; Holst — точки с шагом 24 px. Растягивается на любой размер.";
  gridSet(set, 2, 40);
  return set;
}

