async function buildDrawSettings() {
  const comp = figma.createComponent();
  comp.name = "Draw Settings";
  comp.description = "Толщина и цвет кисти.";
  comp.layoutMode = "VERTICAL";
  comp.primaryAxisSizingMode = "AUTO"; comp.counterAxisSizingMode = "FIXED";
  comp.resize(260, 10);
  comp.primaryAxisSizingMode = "AUTO"; comp.counterAxisSizingMode = "FIXED";
  comp.paddingLeft = comp.paddingRight = 20; comp.paddingTop = 20; comp.paddingBottom = 16;
  comp.itemSpacing = 16; comp.cornerRadius = 12;
  comp.fills = solid("#FFFFFF");
  comp.strokes = solid("#EAECF0"); comp.strokeWeight = 1; comp.strokeAlign = "INSIDE";
  comp.effects = shadow();
  const head = autoLayout("HORIZONTAL", { name: "thickness", counterAxisAlignItems: "CENTER" });
  comp.appendChild(head); head.layoutSizingHorizontal = "FILL"; head.primaryAxisAlignItems = "SPACE_BETWEEN";
  head.appendChild(await text("Толщина", "Body/M"));
  head.appendChild(await text("3px", "Body/M"));
  const slider = figma.createFrame(); slider.name = "slider"; slider.fills = []; slider.resize(220, 16); slider.clipsContent = false;
  const track = figma.createRectangle(); track.resize(220, 4); track.y = 6; track.cornerRadius = 2; track.fills = solid("#D0D5DD"); slider.appendChild(track);
  const fill = figma.createRectangle(); fill.resize(22, 4); fill.y = 6; fill.cornerRadius = 2; fill.fills = solid("#475467"); slider.appendChild(fill);
  const knob = figma.createEllipse(); knob.resize(16, 16); knob.x = 16; knob.fills = solid("#475467"); slider.appendChild(knob);
  comp.appendChild(slider);
  const grid = autoLayout("HORIZONTAL", { name: "colors" });
  grid.layoutWrap = "WRAP"; grid.resize(220, 10); grid.primaryAxisSizingMode = "FIXED"; grid.counterAxisSizingMode = "AUTO"; grid.itemSpacing = 10; grid.counterAxisSpacing = 10;
  comp.appendChild(grid);
  DRAW_COLORS.forEach((hex, i) => {
    const sw = figma.createFrame(); sw.name = hex; sw.resize(36, 36); sw.cornerRadius = 18; sw.fills = [];
    if (i === 0) { sw.strokes = solid("#0A76FA"); sw.strokeWeight = 2; sw.strokeAlign = "INSIDE"; }
    const c = figma.createEllipse(); c.resize(28, 28); c.x = 4; c.y = 4; c.fills = solid(hex);
    c.strokes = solid(darken(hex, 0.85)); c.strokeWeight = 1; c.strokeAlign = "INSIDE";
    sw.appendChild(c); grid.appendChild(sw);
  });
  const dv = divider(false); comp.appendChild(dv); dv.layoutSizingHorizontal = "FILL";
  const wheel = figma.createEllipse(); wheel.name = "custom color"; wheel.resize(32, 32);
  wheel.fills = [{ type: "GRADIENT_ANGULAR", gradientTransform: [[1, 0, 0], [0, 1, 0]], gradientStops: [
    { position: 0, color: { r: 1, g: 0, b: 0, a: 1 } }, { position: 0.17, color: { r: 1, g: 1, b: 0, a: 1 } },
    { position: 0.33, color: { r: 0, g: 1, b: 0, a: 1 } }, { position: 0.5, color: { r: 0, g: 1, b: 1, a: 1 } },
    { position: 0.67, color: { r: 0, g: 0, b: 1, a: 1 } }, { position: 0.83, color: { r: 1, g: 0, b: 1, a: 1 } },
    { position: 1, color: { r: 1, g: 0, b: 0, a: 1 } }] }];
  comp.appendChild(wheel);
  return comp;
}

